Future<void> load() async{var sp=await SharedPreferences.getInstance();var r=sp.getString('roster');if(r!=null)roster=Map<String,String>.from(jsonDecode(r));var rn=sp.getString('note');if(rn!=null)rosterNote=Map<String,String>.from(jsonDecode(rn));var d=sp.getString('defs');if(d!=null){try{var m=Map<String,dynamic>.from(jsonDecode(d));defs=m.map((k,v)=>MapEntry(k,ShiftDef.fromJson(v)));}catch(_){}}var p=sp.getString('pattern');if(p!=null){try{var l=jsonDecode(p) as List;pattern=l.map<List<String>>((row)=>(row as List).map<String>((e)=>e.toString()).toList()).toList();}catch(_){}}var spats=sp.getString('savedPatterns');if(spats!=null){try{savedPatterns=(jsonDecode(spats) as List).map<Map<String,dynamic>>((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){}}setState((){carry=sp.getDouble('carry')??0;customName=sp.getString('cName')??'我的排更';nameCtrl.text=customName;standardWeeklyHours=sp.getDouble('stdWeek')??44;});}
Future<void> save() async{var sp=await SharedPreferences.getInstance();sp.setString('roster',jsonEncode(roster));sp.setString('note',jsonEncode(rosterNote));sp.setString('defs',jsonEncode(defs.map((k,v)=>MapEntry(k,v.toJson()))));sp.setString('pattern',jsonEncode(pattern));sp.setDouble('carry',carry);sp.setString('cName',customName);sp.setString('savedPatterns',jsonEncode(savedPatterns));sp.setDouble('stdWeek',standardWeeklyHours);}
int isoWeek(DateTime d){var jan1=DateTime(d.year,1,1);return 1+((d.difference(jan1).inDays+jan1.weekday-1)/7).floor();}
void quickJumpMonth(){int y=focused.year;int m=focused.month;showDialog(context:context,builder:(ctx){return StatefulBuilder(builder:(ctx2,setD){return AlertDialog(title:const Text('快速查找年月'),content:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[IconButton(icon:const Icon(Icons.remove),onPressed:()=>setD(()=>y--)),Expanded(child:Text('$y年',textAlign:TextAlign.center,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(icon:const Icon(Icons.add),onPressed:()=>setD(()=>y++))]),Wrap(spacing:8,children:List.generate(12,(i){int mon=i+1;bool sel=mon==m;return ChoiceChip(label:Text('${mon}月'),selected:sel,onSelected:(_)=>setD(()=>m=mon));})]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx2),child:const Text('取消')),FilledButton(onPressed:(){setState(()=>focused=DateTime(y,m,1));Navigator.pop(ctx2);},child:const Text('跳轉'))]);});});}
