Container(padding:const EdgeInsets.fromLTRB(12,8,12,12),decoration:BoxDecoration(color:Colors.white,border:Border(top:BorderSide(color:Colors.grey.shade200))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('${DateFormat('MM/dd EEE').format(selectedDay)} ${hkHolidays[selKey]??''}',style:const TextStyle(fontSize:14,fontWeight:FontWeight.bold))),if(selDef!=null)Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:3),decoration:BoxDecoration(color:selDef.color,borderRadius:BorderRadius.circular(12)),child:Text(roster[selKey]??'',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold)))]),if(selDef!=null)Padding(padding:const EdgeInsets.only(top:4),child:Text('班次:${selDef.label} | 工時:${selDef.hours}h | OT:${selDef.ot}h | 津貼:\$${selDef.allowance} | 記事:${rosterNote[selKey]??'無'}',style:const TextStyle(fontSize:12))),SizedBox(width:double.infinity,child:OutlinedButton.icon(onPressed:(){showDetail(selectedDay);},icon:const Icon(Icons.edit,size:16),label:const Text('編輯此日')))])),
