void showDetail(DateTime day){String k=DateFormat('yyyy-MM-dd').format(day);String cur=roster[k]??'';var nc=TextEditingController(text:rosterNote[k]??'');showModalBottomSheet(context:context,isScrollControlled:true,builder:(ctx){return StatefulBuilder(builder:(ctx2,setM){return Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(ctx2).viewInsets.bottom),child:Padding(padding:const EdgeInsets.all(16),child:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[Text(DateFormat('yyyy-MM-dd EEE').format(day),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const Spacer(),if(hkHolidays[k]!=null)Text(hkHolidays[k]!,style:const TextStyle(color:Colors.red))]),Wrap(spacing:8,children:defs.keys.map((c)=>ChoiceChip(label:Text(c),selected:cur==c,onSelected:(_)=>setM(()=>cur=c))).toList()),if(cur.isNotEmpty&&defs[cur]!=null)Container(padding:const EdgeInsets.all(8),decoration:BoxDecoration(color:Colors.grey.shade100,borderRadius:BorderRadius.circular(8)),child:Text('工時:${defs[cur]!.hours}h 津貼:\$${defs[cur]!.allowance} OT:${defs[cur]!.ot}h')),TextField(controller:nc,decoration:const InputDecoration(labelText:'記事 超時工作')),Row(children:[Expanded(child:OutlinedButton(onPressed:(){setState((){roster.remove(k);rosterNote.remove(k);});save();Navigator.pop(ctx2);},child:const Text('清除'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:(){setState((){if(cur!=''){roster[k]=cur;rosterNote[k]=nc.text;}});save();Navigator.pop(ctx2);},child:const Text('儲存')))])])));});});}
Future<void> pickRangeAndApply() async{try{DateTimeRange? picked=await showDateRangePicker(context:context,initialDateRange:DateTimeRange(start:DateTime(focused.year,focused.month,1),end:DateTime(focused.year,focused.month+1,0)),firstDate:DateTime(2023),lastDate:DateTime(2030));if(picked==null)return;List<String> flat=pattern.expand((e)=>e).toList();if(flat.isEmpty)return;setState((){int idx=0;for(DateTime d=picked.start;!d.isAfter(picked.end);d=d.add(const Duration(days:1))){roster[DateFormat('yyyy-MM-dd').format(d)]=flat[idx%flat.length];idx++;}});save();setState(()=>tab=0);}catch(e){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('失敗 $e')));}}
