Widget reportTab(){int dim=DateTime(focused.year,focused.month+1,0).day;Map<String,int> cnt={};double hrs=0,allow=0,ot=0;Map<String,double> allowByCode={};Map<int,double> weeklyHours={};for(int i=1;i<=dim;i++){DateTime dt=DateTime(focused.year,focused.month,i);String k=DateFormat('yyyy-MM-dd').format(dt);String? c=roster[k];if(c==null)continue;cnt[c]=(cnt[c]??0)+1;var d=defs[c];if(d!=null){hrs+=d.hours;allow+=d.allowance;ot+=d.ot;allowByCode[c]=(allowByCode[c]??0)+d.allowance;int w=isoWeek(dt);weeklyHours[w]=(weeklyHours[w]??0)+d.hours;}}return SafeArea(child:ListView(padding:const EdgeInsets.all(12),children:[Text('${focused.year}年${focused.month}月 報表',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('班次資料',style:TextStyle(fontWeight:FontWeight.bold)),...cnt.entries.map((e){var d=defs[e.key];return Row(children:[Text('${e.key} ${d?.label??''}'),const Spacer(),Text('x${e.value} ${d!=null?'${(d.hours*e.value).toStringAsFixed(1)}h / \$${(d.allowance*e.value).toStringAsFixed(1)}':''}')]);})]))),Card(color:const Color(0xFFE3F2FD),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('每週工時與差額 (標準44h)',style:TextStyle(fontWeight:FontWeight.bold)),...weeklyHours.entries.map((e){double diff=e.value-standardWeeklyHours;return Row(children:[Text('W${e.key}'),const Spacer(),Text('${e.value.toStringAsFixed(1)}h'),SizedBox(width:12,child:Text('${diff>=0?'+':''}${diff.toStringAsFixed(1)}',style:TextStyle(color:diff>0?Colors.red:Colors.green)))]);}),Divider(),Text('總工時 ${hrs.toStringAsFixed(1)}h')]))),Card(color:const Color(0xFFE8F5E9),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('津貼類別',style:TextStyle(fontWeight:FontWeight.bold)),...allowByCode.entries.map((e)=>Row(children:[Text(e.key),Spacer(),Text('\$${e.value.toStringAsFixed(1)}')])),Divider(),Text('總津貼 \$${allow.toStringAsFixed(1)} OT ${ot.toStringAsFixed(1)}h')])))]));}
Future<void> backupLocalFile() async{var dir=await getApplicationDocumentsDirectory();var f=File('${dir.path}/roster_backup.json');await f.writeAsString(jsonEncode({'roster':roster,'note':rosterNote,'defs':defs.map((k,v)=>MapEntry(k,v.toJson())),'pattern':pattern,'carry':carry,'cName':customName,'savedPatterns':savedPatterns}));ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('已備份 ${f.path}')));}
Future<void> restoreLocalFile() async{var res=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json']);if(res==null)return;String c=await File(res.files.single.path!).readAsString();var j=jsonDecode(c);setState((){roster=Map<String,String>.from(j['roster']);rosterNote=Map<String,String>.from(j['note']);customName=j['cName'];nameCtrl.text=customName;});save();}
Future<void> exportICS() async{var dir=await getApplicationDocumentsDirectory();var f=File('${dir.path}/$customName.ics');await f.writeAsString('BEGIN:VCALENDAR');ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('已匯出 ${f.path}')));}
